export const skillIcons = {
  "attack": AttackIcon,
  "hitpoints": HitpointsIcon,
  "mining": MiningIcon,
  "strength": StrengthIcon,
  "agility": AgilityIcon,
  "smithing": SmithingIcon,
  "defence": DefenceIcon,
  "herblore": HerbloreIcon,
  "fishing": FishingIcon,
  "ranged": RangedIcon,
  "thieving": ThievingIcon,
  "cooking": CookingIcon,
  "prayer": PrayerIcon,
  "crafting": CraftingIcon,
  "firemaking": FiremakingIcon,
  "magic": MagicIcon,
  "fletching": FletchingIcon,
  "woodcutting": WoodcuttingIcon,
  "runecraft": RunecraftIcon,
  "slayer": SlayerIcon,
  "farming": FarmingIcon,
  "construction": ConstructionIcon,
  "hunter": HunterIcon,
  "sailing": SailingIcon,
  "total": TotalIcon,
} as const;

export type SkillSpriteName = keyof typeof skillIcons;

export type OsrsIconProps = import("@/lib/sprite").SpriteProps;

export function SkillIcon({ skill, ...props }: OsrsIconProps & { skill: SkillSpriteName }) {
  const Icon = skillIcons[skill];
  return <Icon {...props} />;
}
